    public static String getItemName(int idx) {
        return items.getOrDefault(idx, "Nieznany przedmiot (" + idx + ")");
    }

    public static int getItemId(String name) {
        if (name == null || name.trim().isEmpty()) return 65535;
        for (Map.Entry<Integer, String> entry : items.entrySet()) {
            if (entry.getValue().equalsIgnoreCase(name.trim())) {
                return entry.getKey();
            }
        }
        return 65535;
    }

    public static List<String> getAllItemNames() {
        List<String> list = new ArrayList<>();
        for (Map.Entry<Integer, String> entry : items.entrySet()) {
            if (entry.getKey() != 65535) {
                list.add(entry.getValue());
            }
        }
        return list;
    }

    public static String getRandomItemName() {
        List<String> validItems = getAllItemNames();
        if (validItems.isEmpty()) return "Puste";
        return validItems.get(random.nextInt(validItems.size()));
    }
